"use client";

import Link from "next/link";
import { createContext, useContext, useEffect, useMemo, useState } from "react";
import { defaultLocale, homeContent, type HomeContent, type Locale } from "../content/home";

type LocaleContextValue = {
  locale: Locale;
  setLocale: (locale: Locale) => void;
  content: HomeContent;
};

const LocaleContext = createContext<LocaleContextValue | null>(null);

function LanguageSwitcher({
  locale,
  onChange,
  labels,
}: {
  locale: Locale;
  onChange: (locale: Locale) => void;
  labels: { languageLabel: string; norwegian: string; english: string };
}) {
  return (
    <div className="flex items-center gap-2 text-[11px] uppercase tracking-[0.12em] text-[#111111]/65">
      <span className="hidden lg:inline">{labels.languageLabel}</span>
      <div className="flex rounded-full border border-[#D4D4CF] bg-[#ECECE8] p-1">
        {([
          ["no", labels.norwegian],
          ["en", labels.english],
        ] as const).map(([value, label]) => {
          const active = locale === value;
          return (
            <button
              key={value}
              type="button"
              onClick={() => onChange(value)}
              className={`rounded-full px-3 py-1 transition-colors ${
                active ? "bg-[#FFFFFF] text-[#111111] shadow-[0_1px_2px_rgba(17,17,17,0.08)]" : "text-[#111111]/58"
              }`}
              aria-pressed={active}
            >
              {label}
            </button>
          );
        })}
      </div>
    </div>
  );
}

function SiteHeader() {
  const { locale, setLocale, content } = useLocale();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const navItems = [
    { href: "/tjenester", label: "Tjenester" },
    { href: "/arbeider", label: "Arbeider" },
    { href: "/partner", label: "Paid Media" },
    { href: "/om", label: "Om Apriil" },
    { href: "/kontakt", label: "Kontakt oss" },
  ];

  return (
    <header className="border-b border-[#DBDBD7] bg-[#F4F4F2]">
      <div className="mx-auto grid w-full max-w-[1440px] grid-cols-[auto_1fr_auto] items-center gap-4 px-6 py-5 md:gap-6 md:px-10 xl:px-16">
        <Link href="/" className="justify-self-start text-[30px] font-medium leading-none tracking-[0.08em] text-[#111111]">
          APRIIL
        </Link>

        <nav
          aria-label="Hovednavigasjon"
          className="hidden items-center justify-center gap-8 text-[18px] font-medium leading-none tracking-[-0.01em] text-[#111111] md:flex"
        >
          {navItems.map((item) => (
            <Link key={item.href} href={item.href} className="animated-link">
              {item.label}
            </Link>
          ))}
        </nav>

        <div className="flex items-center justify-self-end gap-4">
          <div className="hidden md:block">
            <LanguageSwitcher locale={locale} onChange={setLocale} labels={content.navigation} />
          </div>
          <form role="search" aria-label="Nettstedsok" className="hidden w-full max-w-[240px] md:block">
            <div className="relative">
              <svg
                aria-hidden="true"
                viewBox="0 0 24 24"
                className="pointer-events-none absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-[#8A8A86]"
              >
                <path
                  d="M15.5 15.5L21 21M18 10.5A7.5 7.5 0 1 1 3 10.5a7.5 7.5 0 0 1 15 0Z"
                  stroke="currentColor"
                  strokeWidth="1.8"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  fill="none"
                />
              </svg>
              <input
                id="site-search"
                type="search"
                name="q"
                placeholder="Søk"
                className="h-11 w-full rounded-full border border-[#7C7C78] bg-transparent pl-11 pr-4 text-[16px] text-[#111111] outline-none transition-colors focus:border-[#4E4E4A]"
              />
            </div>
          </form>
          <button
            type="button"
            aria-expanded={mobileMenuOpen}
            aria-controls="mobile-site-menu"
            aria-label={mobileMenuOpen ? "Lukk meny" : "Åpne meny"}
            onClick={() => setMobileMenuOpen((open) => !open)}
            className="inline-flex h-11 w-11 items-center justify-center rounded-full border border-[#7C7C78] text-[#111111] transition-colors hover:border-[#4E4E4A] md:hidden"
          >
            <span className="sr-only">Meny</span>
            <svg aria-hidden="true" viewBox="0 0 24 24" className="h-5 w-5">
              {mobileMenuOpen ? (
                <path
                  d="M6 6l12 12M18 6 6 18"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                />
              ) : (
                <path
                  d="M4 7h16M4 12h16M4 17h16"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                />
              )}
            </svg>
          </button>
        </div>
      </div>

      {mobileMenuOpen ? (
        <div id="mobile-site-menu" className="border-t border-[#DBDBD7] px-6 pb-6 pt-4 md:hidden">
          <div className="mx-auto flex w-full max-w-[1440px] flex-col gap-5">
            <nav aria-label="Mobil navigasjon" className="flex flex-col gap-3 text-[18px] font-medium tracking-[-0.01em] text-[#111111]">
              {navItems.map((item) => (
                <Link
                  key={item.href}
                  href={item.href}
                  onClick={() => setMobileMenuOpen(false)}
                  className="rounded-[16px] border border-[#DAD9D4] bg-[#F9F9F7] px-4 py-3"
                >
                  {item.label}
                </Link>
              ))}
            </nav>

            <div className="flex flex-col gap-3">
              <LanguageSwitcher locale={locale} onChange={setLocale} labels={content.navigation} />
              <form role="search" aria-label="Nettstedsok mobil">
                <div className="relative">
                  <svg
                    aria-hidden="true"
                    viewBox="0 0 24 24"
                    className="pointer-events-none absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-[#8A8A86]"
                  >
                    <path
                      d="M15.5 15.5L21 21M18 10.5A7.5 7.5 0 1 1 3 10.5a7.5 7.5 0 0 1 15 0Z"
                      stroke="currentColor"
                      strokeWidth="1.8"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      fill="none"
                    />
                  </svg>
                  <input
                    id="mobile-site-search"
                    type="search"
                    name="q"
                    placeholder="Søk"
                    className="h-11 w-full rounded-full border border-[#7C7C78] bg-transparent pl-11 pr-4 text-[16px] text-[#111111] outline-none transition-colors focus:border-[#4E4E4A]"
                  />
                </div>
              </form>
            </div>
          </div>
        </div>
      ) : null}
    </header>
  );
}

export function LocaleShell({ children }: { children: React.ReactNode }) {
  const [locale, setLocale] = useState<Locale>(defaultLocale);

  useEffect(() => {
    document.documentElement.lang = locale === "no" ? "no" : "en";
  }, [locale]);

  const value = useMemo(
    () => ({ locale, setLocale, content: homeContent[locale] }),
    [locale],
  );

  return (
    <LocaleContext.Provider value={value}>
      <SiteHeader />
      {children}
    </LocaleContext.Provider>
  );
}

export function useLocale() {
  const context = useContext(LocaleContext);

  if (!context) {
    throw new Error("useLocale must be used within LocaleShell");
  }

  return context;
}