export function getSearchFooterSections(locale: Locale) {
  const orderedClusters: SearchClusterKey[] = [
    "seo-basics",
    "content-optimisation",
    "ai-search-geo",
    "technical-performance",
  ];

  return orderedClusters.map((cluster) => ({
    title: clusterTitles[locale][cluster],
    links: searchQuestionMap
      .filter((entry) => entry.locale === locale && entry.cluster === cluster)
      .map((entry) => ({ label: entry.question, href: entry.path })),
  }));
}

export function getAllSearchQuestionPaths() {
  return searchQuestionMap.map((entry) => entry.path);
}

export function getSearchQuestionByPath(path: string, locale?: Locale) {
  const normalizedPath = path.startsWith("/") ? path : `/${path}`;
  const exact = searchQuestionMap.find(
    (entry) => entry.path === normalizedPath && (!locale || entry.locale === locale),
  );

  return exact || null;
}
